// Map turns a []T into a []U using f.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s))
	for i, v := range s {
		out[i] = f(v)
	}
	return out
}

func main() {
	// T=int and U=string are both inferred.
	xs := Map([]int{1, 2, 3}, strconv.Itoa)
	fmt.Println(xs) // [1 2 3]
}
